    for (let x = 0x0; x + 0x2 < g['length']; x += 0x3) {
        const A = g[x], B = g[x + 0x1], C = g[x + 0x2];
        w += t[s['DfLEy'](A, 0x2) & 0x3f], w += t[(A & 0x3) << 0x4 | B >> 0x4 & 0xf], w += t[s[a5(0x938)](B & 0xf, 0x2) | s[a5(0x15be)](C >> 0x6, 0x3)], w += t[C & 0x3f];
